    async def on_replace_merged_instrument(self, heard: Heard[ops.InstrumentReplacedEvent]) -> None:
        """W3.8: A deployment's record was replaced by another (W3.8): from contract v10, a
        record a person merged into the one that stays (W3.13); before it, a placeholder by its
        INS- ID. Optional: heard only where a class overrides it."""

    async def on_position_changed(self, heard: Heard[ops.PositionChangedEvent]) -> None:
        """W9.8: PositionChanged. Optional: heard only where a class overrides it."""

